<script lang="ts">
  import { onMount,onDestroy,untrack,tick } from 'svelte';
  import type { Story } from './story';
  import type { PublicConnections } from './settings';
  import { promptSettingsSchema } from './settings';
  import { normalizeStockImageTemplate } from './image-prompts';
  import { illustrationDraftSchema,illustrationVariables,shotDetailGroups,shotDetailLabels,resolveIllustration,illustrationSourceKey,subjectFromCharacter,fillFromSavedProfiles,usesCurrentCharacterState,visualIdentityToRemember,reframeIllustration,type IllustrationDraft,type IllustrationCapture } from './illustration';
  import { illustrationContentPolicy } from './illustration';
  import { identityFields,identityLabels,visualIdentitySchema } from './visual-identity';
  import { normalizeCharacterProfile } from './character-profile';
  import { reportUiError } from './ui-feedback';
  import MediaSubjectPicker from './MediaSubjectPicker.svelte';
  let {story,connections,initialCharacterId='',initialPassageId='',initialParentId='',busy=false,onSaved,onOpen,onBack}:{story:Story;connections:PublicConnections|null;initialCharacterId?:string;initialPassageId?:string;initialParentId?:string;busy?:boolean;onSaved:(s:Story)=>void;onOpen:(asset:string,person:string)=>void;onBack:()=>void}=$props();
  const needsPromptDefaults=untrack(()=>!connections&&!initialParentId);
  function initialDraft() {
    const parent=story.media.assets.find(a=>a.id===initialParentId),previous=illustrationDraftSchema.safeParse(parent?.provenance.composition);
    if(parent&&previous.success)return {...previous.data,template:normalizeStockImageTemplate(previous.data.template),parentId:parent.id};
    const people=story.canon.characters,person=initialCharacterId || people.find(c=>c.name===story.passages.find(p=>p.id===initialPassageId)?.viewpoint)?.id || '';
    const framing=people.some(c=>c.id===initialCharacterId)?'portrait':'scene',prompts=promptSettingsSchema.parse(connections?.prompts || {});
    return illustrationDraftSchema.parse({framing,subjectIds:person?[person]:[],subjects:people.some(c=>c.id===person)?[subjectFromCharacter(people.find(c=>c.id===person)!,framing,usesCurrentCharacterState(story,initialPassageId||null))]:[],passageId:initialPassageId || null,parentId:initialParentId || null,promptMode:'natural',style:story.artStyle,scene:'',background:'',template:framing==='portrait'?prompts.portrait:prompts.group,negative:prompts.negative});
  }
  let draft=$state<IllustrationDraft>(untrack(initialDraft)),images=$state<PublicConnections['images']|null>(untrack(()=>connections?structuredClone($state.snapshot(connections.images)):null));
  const reusesParent=untrack(()=>illustrationDraftSchema.safeParse(story.media.assets.find(a=>a.id===initialParentId)?.provenance.composition).success);
  let preparedSceneFocus=$state(untrack(()=>reusesParent?draft.sceneFocus:''));
  let autoRefresh=$state(true),preparedSource=$state(untrack(()=>reusesParent?illustrationSourceKey(story,draft):'')),preparation=$state<'none'|'story'|'manual'>(reusesParent?'manual':'none'),refreshing=$state(false);
  let defaults=$state(untrack(()=>promptSettingsSchema.parse(connections?.prompts || {}))),canSuggest=$state(untrack(()=>Boolean(connections?.text.model)));
  let loading=$state(true),working=$state(false),error=$state(''),note=$state(''),tab=$state('compose'),variable=$state('subjects'),override=$state(false);
  let sceneFocusInput=$state<HTMLTextAreaElement>();
  let copyFeedback=$state<{text:string;captured:boolean;ok:boolean}|null>(null);
  let workflows=$state<{name:string;path:string}[]>([]),workflowInfo=$state<{nodes:{id:string;type:string;inputs:string[]}[]}|null>(null);
  type PictureJob={id:string;status:'queued'|'complete'|'error';error?:string;seed:number|null;durationMs:number;images:string[];capture:IllustrationCapture};
  let jobs=$state<PictureJob[]>([]),selectedJobId=$state(''),outputIndex=$state(0),caption=$state(''),saveStatus=$state<'canonical'|'experimental'>('canonical'),setPortrait=$state(false);
  let jobSearch=$state(''),jobStatus=$state('all');
  let mounted=false,alive=true,timer:ReturnType<typeof setTimeout>|undefined;
  let controller=$state<AbortController>();
  let preparationRequestId:string|null=null;
  let pending:{key:string;requestId:string}|null=null,acceptRequest:{key:string;requestId:string}|null=null;
  const entities=$derived([...story.canon.characters.map(entity=>({...entity,kind:'Cast'})),...story.canon.places.map(entity=>({...entity,kind:'Place'})),...story.canon.items.map(entity=>({...entity,kind:'Item'}))]);
  const visibleJobs=$derived(jobs.filter(entry=>(jobStatus==='all'||entry.status===jobStatus)&&[entry.capture.source?.title||'Reference art',...entry.capture.snapshots.map(snapshot=>snapshot.name)].join(' ').toLocaleLowerCase().includes(jobSearch.trim().toLocaleLowerCase())));
  const people=$derived(story.canon.characters.filter(c=>draft.subjectIds.includes(c.id)));
  const contentPolicy=$derived(illustrationContentPolicy(story,draft));
  const job=$derived(jobs.find(j=>j.id===selectedJobId));
  const activeJob=$derived(jobs.find(j=>j.status==='queued'));
  const validDimensions=$derived(Boolean(images&&Number.isFinite(images.width)&&Number.isFinite(images.height)&&images.width>0&&images.height>0));
  const landscape=$derived(Boolean(images&&images.width>images.height));
  const canChangeOrientation=$derived(Boolean(images&&validDimensions&&images.width!==images.height&&images.bindings.width&&images.bindings.height));
  const source=$derived(story.passages.find(p=>p.id===draft.passageId));
  const sourceKey=$derived(illustrationSourceKey(story,draft));
  const focusChanged=$derived(Boolean(draft.passageId&&draft.sceneFocus.trim()!==preparedSceneFocus.trim()));
  const needsRefresh=$derived(preparedSource!==sourceKey||focusChanged);
  const savedOutput=$derived(job?story.media.assets.find(a=>a.provenance.generationId===job.id && a.provenance.outputIndex===outputIndex):undefined);
  const resolved=$derived.by(()=>{try{if(override&&!draft.promptOverride.trim())throw new Error('Enter a one-image prompt override, or turn the override off to use the template.');return {...resolveIllustration(story,draft),error:''};}catch(e){return {text:'',omitted:[],protectedNames:[],error:e instanceof Error?e.message:'Invalid composition.'};}});
  const labels:Record<string,string>={...identityLabels,appearanceNotes:'Additional visible features',outfitNotes:'Additional clothing details',injuries:'Visible injuries / condition',upper_body:'Visible upper body & clothing',lower_body:'Visible lower body & clothing',footwear:'Footwear',accessories:'Visible accessories',pose:'Pose / position',expression:'Expression'};
  const shotFields=['appearanceNotes','outfitNotes','upper_body','lower_body','footwear','accessories','injuries','pose','expression'] as const;
  const cacheKey=()=>`guided-story-illustration-${story.id}`;
  $effect(()=>{if(error)untrack(()=>reportUiError(error,'Illustration studio'));});
  $effect(()=>{if(resolved.error)untrack(()=>reportUiError(resolved.error,'Illustration studio · prompt'));});
  $effect(()=>{if(job?.error)untrack(()=>reportUiError(job!.error!,'Illustration studio · generation'));});
  $effect(()=>{const payload=JSON.stringify({draft,images,autoRefresh,preparedSource,preparedSceneFocus,preparation});if(mounted&&!loading){try{localStorage.setItem(cacheKey(),payload);}catch{/* Generation and saved jobs remain available if device storage is full. */}}});
  async function json(r:Response){const b=await r.json();if(!r.ok)throw new Error(b.error || 'The illustration request failed.');return b;}
  const post=(path:string,body:unknown,signal?:AbortSignal)=>fetch(`/api/stories/${story.id}/illustrations${path}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body),signal}).then(json);
  function syncSubjects(){draft.subjects=story.canon.characters.filter(c=>draft.subjectIds.includes(c.id)).map(c=>draft.subjects.find(s=>s.id===c.id)||subjectFromCharacter(c,draft.framing,usesCurrentCharacterState(story,draft.passageId)));for(const s of draft.subjects)if(s.shot.gaze.startsWith('character:')&&!draft.subjects.some(other=>other.id===s.shot.gaze.slice(10)&&other.id!==s.id))s.shot.gaze='automatic';}
  function manualDetails(){if(!draft.passageId)preparedSource=illustrationSourceKey(story,draft);preparation='manual';}
  function manualSceneDetails(){preparedSource=illustrationSourceKey(story,draft);preparedSceneFocus=draft.sceneFocus;manualDetails();}
  async function useMoment(paragraph:string){
    if(loading||working||busy||override||paragraph.length>2000)return;
    draft.sceneFocus=paragraph;note='Source paragraph selected. Refresh the prompt to review this moment, or generate with automatic refresh.';
    await tick();sceneFocusInput?.scrollIntoView({block:'center'});sceneFocusInput?.focus({preventScroll:true});
  }
  function clearMoment(){if(working||busy||override)return;draft.sceneFocus='';note='Selected moment cleared. Refresh the prompt for automatic moment selection.';}
  async function copyPrompt(text:string,captured=false){
    if(!text)return;
    try{await navigator.clipboard.writeText(text);copyFeedback={text,captured,ok:true};error='';note=captured?'Captured prompt copied.':'Resolved prompt copied.';}
    catch{copyFeedback={text,captured,ok:false};error='Could not copy the prompt. Select the prompt text and copy it manually.';}
  }
  function changeFraming(next:IllustrationDraft['framing']){draft=reframeIllustration(story,$state.snapshot(draft),next);draft.template=draft.framing==='scene'?defaults.group:defaults[draft.framing];draft.promptOverride='';override=false;}
  function changeOrientation(wide:boolean){
    if(!images||!canChangeOrientation||loading||working||busy)return;
    const short=Math.min(images.width,images.height),long=Math.max(images.width,images.height);
    images={...images,width:wide?long:short,height:wide?short:long};
  }
  function selectJob(j:PictureJob){selectedJobId=j.id;outputIndex=0;caption=j.capture.source?.title || j.capture.snapshots.map(s=>s.name).join(', ') || 'Story illustration';setPortrait=j.capture.draft.framing==='portrait' && j.capture.draft.subjects.length===1;error='';}
  async function refreshJobs(poll=true){
    const list=await json(await fetch(`/api/stories/${story.id}/illustrations`));
    let rows:PictureJob[]=list.jobs;
    if(poll){const outcomes=await Promise.allSettled(rows.filter(j=>j.status==='queued').map(async j=>({...j,...await json(await fetch(`/api/stories/${story.id}/illustrations/${j.id}`))})));
      for(const outcome of outcomes){if(outcome.status==='fulfilled')rows=rows.map(j=>j.id===outcome.value.id?outcome.value:j);else if(alive)error=outcome.reason instanceof Error?outcome.reason.message:'Could not check an illustration.';}}
    if(alive){jobs=rows;if(!selectedJobId&&rows[0])selectJob(rows[0]);}
  }
  async function watch(){if(!alive)return;try{await refreshJobs();}catch(e){if(alive)error=e instanceof Error?e.message:'Could not refresh illustrations.';}finally{if(alive)timer=setTimeout(watch,4000);}}
  async function inspectWorkflow(){if(!images)return;working=true;error='';try{const info=await json(await fetch('/api/workflows?path='+encodeURIComponent(images.workflow)));workflowInfo=info;images.bindings=info.suggested;note='Suggested bindings loaded. Check the mapped nodes before generating.';}catch(e){error=e instanceof Error?e.message:'Could not inspect workflow.';}finally{working=false;}}
  async function preparePrompt(mode:'refresh'|'fill-missing'='refresh'){
    const previous=illustrationSourceKey(story,draft),sceneWasCurrent=preparedSource===previous&&!focusChanged,hadScene=Boolean(draft.scene.trim());controller=new AbortController();refreshing=true;preparationRequestId=crypto.randomUUID();
    try{
      const next=await post('/prepare',{expectedRevision:story.revision,requestId:preparationRequestId,draft:$state.snapshot(draft),mode},controller.signal);
      if(controller.signal.aborted)throw new Error('Prompt refresh cancelled. No image was queued.');
      if(previous!==illustrationSourceKey(story,draft))throw new Error('The illustration source changed during refresh. Review it and refresh again.');
      draft=illustrationDraftSchema.parse(next);if(mode==='refresh'||sceneWasCurrent||!hadScene)preparedSource=illustrationSourceKey(story,draft);if(mode==='refresh')preparedSceneFocus=draft.sceneFocus;preparation=mode==='fill-missing'?'manual':'story';await tick();
    }finally{refreshing=false;preparationRequestId=null;}
  }
  async function cancelPrompt(){const current=controller,id=preparationRequestId;current?.abort();if(!id)return;try{await json(await fetch('/api/generation/cancel',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({storyId:story.id,requestId:id}),signal:AbortSignal.timeout(5000)}));}catch{if(alive)note='The image submission was stopped. Check Dev → Jobs if provider cancellation was not confirmed.';}}
  async function suggest(mode:'refresh'|'fill-missing'='refresh'){if(working||busy||override)return;working=true;error='';note=mode==='fill-missing'?'Suggesting missing visible details…':'Refreshing shot details from the saved story…';try{await preparePrompt(mode);note=mode==='fill-missing'?'Missing details suggested for this image. Review them; use Remember visual identity to keep them for future pictures.':'Visual details suggested. Review the shot and resolved prompt before generating.';}catch(e){error=controller?.signal.aborted?'Prompt refresh cancelled. Your prior visual details are kept.':e instanceof Error?e.message:'Could not refresh the prompt.';note='';}finally{working=false;controller=undefined;}}
  function fillSaved(){draft=fillFromSavedProfiles(story,draft);note=usesCurrentCharacterState(story,draft.passageId)?'Blank fields filled from saved profiles. Your existing shot details were kept.':'Blank identity fields filled from saved profiles. Current clothing and injuries were not copied into this earlier passage.';}
  function rememberedVisual(id:string){const c=story.canon.characters.find(c=>c.id===id),s=draft.subjects.find(s=>s.id===id);return c&&s?visualIdentityToRemember(c,s,draft.framing):visualIdentitySchema.parse({});}
  async function rememberIdentity(id:string){
    const c=story.canon.characters.find(c=>c.id===id),s=draft.subjects.find(s=>s.id===id);if(!c||!s||working||busy)return;
    const sceneWasCurrent=preparedSource===illustrationSourceKey(story,draft)&&!focusChanged;
    working=true;error='';
    try{const saved:Story=await json(await fetch(`/api/stories/${story.id}`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({expectedRevision:story.revision,requestId:crypto.randomUUID(),action:{type:'character',character:normalizeCharacterProfile({...c,visual:rememberedVisual(id)})}})}));onSaved(saved);if(sceneWasCurrent)preparedSource=illustrationSourceKey(saved,draft);note=`Visual identity saved for ${c.name}. Future pictures reuse it. Established actual age and gender were kept; clothing, injuries, pose and expression remain specific to this shot.`;}catch(e){error=e instanceof Error?e.message:'Could not remember the visual identity.';}finally{working=false;}
  }
  async function generate(){
    if(!images||working||busy)return;working=true;error='';
    try{
      await tick();syncSubjects();
      if(override&&!draft.promptOverride.trim())throw new Error('Enter a one-image prompt override, or turn the override off to use the template.');
      if(autoRefresh&&canSuggest&&!override&&(preparedSource!==illustrationSourceKey(story,draft)||(draft.passageId&&draft.sceneFocus.trim()!==preparedSceneFocus.trim()))){note='Refreshing the prompt from the story before illustrating…';await preparePrompt();}
      if(controller?.signal.aborted)throw new Error('Prompt refresh cancelled. No image was queued.');
      // Resolve from the current fields at the submission boundary, using the same resolver as the preview/server.
      const current=resolveIllustration(story,$state.snapshot(draft));await tick();controller=undefined;note='Submitting the current resolved prompt to ComfyUI…';
      const body={expectedRevision:story.revision,draft:current.draft,images:$state.snapshot(images)},key=JSON.stringify(body);if(pending?.key!==key)pending={key,requestId:crypto.randomUUID()};
      const result=await post('',{...body,requestId:pending.requestId});pending=null;await refreshJobs(false);const j=jobs.find(j=>j.id===result.id);if(j)selectJob(j);tab='results';note=result.status==='error'?'The previous image request failed. Reuse the shot to start a new request.':'Image queued. You can keep reading; return here to collect the result.';
    }catch(e){error=controller?.signal.aborted?'Prompt refresh cancelled. No image was queued.':e instanceof Error?e.message:'Could not queue the illustration.';note='';}
    finally{working=false;refreshing=false;controller=undefined;}
  }
  async function accept(){if(!job||working||busy)return;working=true;error='';const body={expectedRevision:story.revision,index:outputIndex,caption,status:saveStatus,setPortrait},key=JSON.stringify({jobId:job.id,...body});if(acceptRequest?.key!==key)acceptRequest={key,requestId:crypto.randomUUID()};try{const saved:Story=await post(`/${job.id}/accept`,{...body,requestId:acceptRequest.requestId});onSaved(saved);acceptRequest=null;const a=saved.media.assets.find(a=>a.provenance.generationId===job!.id&&a.provenance.outputIndex===outputIndex);note=a?.status==='superseded'?'Saved as an earlier version: the source passage changed after this image was queued.':'Illustration saved to the gallery and its subjects’ photobooks.';}catch(e){error=e instanceof Error?e.message:'Could not save the illustration.';}finally{working=false;}}
  async function discard(){if(!job||working)return;working=true;error='';try{await json(await fetch(`/api/stories/${story.id}/illustrations/${job.id}`,{method:'DELETE'}));selectedJobId='';await refreshJobs(false);note='Preview discarded. Pictures already saved to the gallery are kept.';}catch(e){error=e instanceof Error?e.message:'Could not discard preview.';}finally{working=false;}}
  function reuse(){if(!job)return;draft=illustrationDraftSchema.parse($state.snapshot(job.capture.draft));draft.template=normalizeStockImageTemplate(draft.template);override=Boolean(draft.promptOverride);manualSceneDetails();if(images)images.seed=-1;pending=null;tab='compose';note='Composition reused with a new seed. Review current story facts, or refresh the prompt from the story.';}
  async function reload(){working=true;error='';try{onSaved(await json(await fetch(`/api/stories/${story.id}`)));await refreshJobs();note='Saved story and image results refreshed. Your shot edits are kept.';}catch(e){error=e instanceof Error?e.message:'Could not refresh the saved story.';}finally{working=false;}}
  onMount(()=>{
    (async()=>{const outcomes=await Promise.allSettled([fetch('/api/connections').then(json),fetch('/api/workflows').then(json),refreshJobs()]);
      if(!alive)return;
      if(outcomes[0].status==='fulfilled'){const c:PublicConnections=outcomes[0].value;images ||=c.images;defaults=c.prompts;canSuggest=Boolean(c.text.model);if(needsPromptDefaults){draft.template=draft.framing==='scene'?c.prompts.group:c.prompts[draft.framing];draft.negative=c.prompts.negative;}}
      if(outcomes[1].status==='fulfilled')workflows=outcomes[1].value;
      for(const outcome of outcomes)if(outcome.status==='rejected')error=outcome.reason instanceof Error?outcome.reason.message:'Could not load illustration settings.';
      try{const cached=JSON.parse(localStorage.getItem(cacheKey()) || 'null');if(cached&&(!initialCharacterId&&!initialPassageId&&!initialParentId)){draft=illustrationDraftSchema.parse(cached.draft);draft.template=normalizeStockImageTemplate(draft.template);if(cached.images)images=cached.images;override=Boolean(draft.promptOverride);autoRefresh=cached.autoRefresh!==false;preparedSource=typeof cached.preparedSource==='string'?cached.preparedSource:'';preparedSceneFocus=typeof cached.preparedSceneFocus==='string'?cached.preparedSceneFocus:'';preparation=['story','manual'].includes(cached.preparation)?cached.preparation:'none';note='Restored your last illustration draft on this device.';}}catch{/* Invalid development draft: use the fresh composition. */}
      loading=false;mounted=true;timer=setTimeout(watch,1000);
    })();
  });
  onDestroy(()=>{alive=false;if(timer)clearTimeout(timer);controller?.abort();});
</script>

<main class="full-view illustration-view">
  <div class="eyebrow">Pictures from your novel</div><div class="heading-row"><h1>Illustration studio</h1><button onclick={onBack}>Back to story ↗</button></div>
  <p class="muted">Compose a portrait or story moment, review the prompt, then generate with ComfyUI. Saving a picture keeps its history and adds it to every depicted subject’s photobook.</p>
  <div class="tabs" role="group" aria-label="Illustration sections"><button class:active={tab==='compose'} aria-pressed={tab==='compose'} onclick={()=>tab='compose'}>Compose</button><button class:active={tab==='results'} aria-pressed={tab==='results'} onclick={()=>tab='results'}>Generations ({jobs.length})</button><button onclick={reload} disabled={working}>Refresh story &amp; results</button></div>
  {#if error}<p class="error" role="alert">{error}</p>{/if}{#if note}<p class="notice" role="status">{note}</p>{/if}
  {#if loading}<p role="status">Loading workflows and illustration history…</p>{/if}
  {#if working}<p class="muted" role="status">{refreshing ? 'Refreshing shot details…' : tab==='results' ? 'Updating the selected illustration…' : 'Updating this composition…'}</p>{/if}
  {#if controller}<button onclick={cancelPrompt}>Cancel prompt refresh</button>{/if}
  {#if tab==='compose'}
    {#if activeJob}<div class="notice"><p>An illustration is already running for this story. You can keep editing the next shot while it finishes.</p><button onclick={()=>{selectJob(activeJob!);tab='results';}}>View active generation</button></div>{/if}
    <fieldset class="illustration-fields" disabled={loading||working||busy}>
      {#if images}<div class="image-orientation"><label class="check"><input type="checkbox" checked={landscape} disabled={!canChangeOrientation} onchange={e=>changeOrientation(e.currentTarget.checked)} aria-describedby="image-orientation-help" />Landscape orientation</label><p class="muted" role="status">Canvas: {#if validDimensions}{landscape?'Landscape':images.width===images.height?'Square':'Portrait'} · {images.width} × {images.height} px{:else}Enter a width and height in generation settings.{/if}</p><p id="image-orientation-help" class="muted">Swaps width and height for this image. Saved defaults stay the same.{#if !images.bindings.width||!images.bindings.height} Map both width and height in Workflow inputs to enable it.{:else if validDimensions&&images.width===images.height} Square dimensions are unchanged; set different sides in generation settings to choose an orientation.{/if}</p></div>{/if}
      <div class="form-grid"><label>Shot framing<select bind:value={draft.framing} onchange={e=>changeFraming(e.currentTarget.value as IllustrationDraft['framing'])}><option value="portrait">Portrait / bust</option><option value="fullbody">Full body</option><option value="scene">Scene / group</option></select></label><label>Source passage<select bind:value={draft.passageId}><option value={null}>Reference art · no story event</option>{#each story.passages as p}<option value={p.id}>Chapter {p.chapter} · {p.title}</option>{/each}</select></label></div>
      {#if source}<label for="illustration-scene-focus">Which part of the scene? (optional)<textarea id="illustration-scene-focus" bind:this={sceneFocusInput} bind:value={draft.sceneFocus} maxlength="2000" rows="3" disabled={override} placeholder="For example: the moment Mira hands over her jacket, before the airlock opens. Or paste a line from the passage." aria-describedby="illustration-scene-focus-help"></textarea></label><div class="row"><button type="button" onclick={clearMoment} disabled={!draft.sceneFocus.length||override}>Clear selected moment</button></div><p id="illustration-scene-focus-help" class="muted">Describe one moment or paste a short excerpt. Refresh prompt from story uses it to choose the action, poses and clothing for that moment. Leave blank to let the narrator choose.{#if override} Turn off the one-image prompt override to use this field.{/if}</p>{#if focusChanged&&(!canSuggest||!autoRefresh)&&!override}<p class="notice muted" role="status">The selected moment changed. {canSuggest?'Choose Refresh prompt from story to apply it, or edit Visible scene / action yourself.':'Configure a text model to extract this moment, or describe it yourself in Visible scene / action.'}</p>{/if}{/if}
      <MediaSubjectPicker {entities} bind:value={draft.subjectIds} onChange={syncSubjects} />
      {#if source}<details><summary>Source passage · {source.title}</summary><div class="illustration-source">{#each source.paragraphs as p,i}<div class="source-moment"><p>{p}</p><button type="button" onclick={()=>useMoment(p)} disabled={override||p.length>2000} aria-label={`Use paragraph ${i+1} as the image moment`} title={p.length>2000?'This paragraph is longer than 2,000 characters. Paste a shorter excerpt into the selected moment field.':'Use this paragraph to choose the moment; no generation starts yet.'}>Use this moment</button></div>{/each}</div></details>{/if}
      <p class="muted">The story and pictures share one saved character profile. Visible identity loads automatically; current clothing and injuries load for reference pictures and the latest passage. Suggestions change this picture until you choose to remember them.</p>
      {#if !usesCurrentCharacterState(story,draft.passageId)}<p class="notice">This is an earlier passage. Refresh to recover its visible clothing, injuries and action from that passage; current character state is not historical evidence. Existing shot edits remain yours to review.</p>{/if}
      <div class="row"><button onclick={fillSaved} disabled={override}>Fill blanks from saved profiles</button><button onclick={()=>suggest()} disabled={!canSuggest||override}>Suggest visual details from story</button><button onclick={()=>suggest('fill-missing')} disabled={!canSuggest||override}>Fill missing details</button></div>
      <p class="muted">Story refresh updates the scene, clothing and poses while keeping entered identity traits. Fill missing details preserves every filled field and may propose unspecified features. Unestablished age and gender stay yours to choose.</p>
      <label>Art direction<textarea bind:value={draft.style} maxlength="4000"></textarea></label><label>Visible scene / action<textarea bind:value={draft.scene} oninput={manualSceneDetails} maxlength="5000" placeholder="One visible moment, including where each subject is positioned…"></textarea></label><label>Background / location<input bind:value={draft.background} oninput={manualDetails} maxlength="2000" /></label>
      <div class="form-grid"><label>Camera &amp; composition<input bind:value={draft.composition} maxlength="2000" placeholder="Eye level, subject at left, shallow depth of field…" /></label><label>Lighting &amp; palette<input bind:value={draft.lighting} maxlength="2000" placeholder="Warm window light, muted teal shadows…" /></label></div>
      {#each people as c,i}{@const s=draft.subjects.find(s=>s.id===c.id)}{#if s}<details class="illustration-subject" open={i===0}><summary>{c.name} · {c.noNsfw?'No NSFW':'Individual adult opt-in'}</summary>
        <fieldset disabled={override}><legend>Shot choices · {c.name}</legend><div class="form-grid">
          <label>{c.name} · Image position<select bind:value={s.shot.position}><option value="automatic">Automatic</option><option value="left">Left</option><option value="center">Center</option><option value="right">Right</option></select></label>
          <label>{c.name} · Depth<select bind:value={s.shot.depth}><option value="automatic">Automatic</option><option value="foreground">Foreground</option><option value="middle">Middle ground</option><option value="background">Background</option></select></label>
          <label>{c.name} · Gaze<select bind:value={s.shot.gaze}><option value="automatic">Automatic</option><option value="camera">At camera</option><option value="elsewhere">Away from camera</option>{#each people.filter(other=>other.id!==c.id) as other}<option value={'character:'+other.id}>At {other.name}</option>{/each}</select></label>
        </div><p class="muted">Include in this picture’s prompt:</p><div class="media-subjects">{#each shotDetailGroups as group}<label class="check"><input type="checkbox" bind:checked={s.shot.include[group]} />{shotDetailLabels[group]}</label>{/each}</div><p class="muted">These choices update the prompt directly and survive story suggestions. Unchecked details stay saved below. Portraits start with build details off and always omit lower-body clothing and footwear. Review free-text scene and pose if they repeat an excluded detail.</p></fieldset>
        <p class="muted">Saved appearance: {c.appearance || 'Unspecified'}<br />Current outfit: {c.outfit || 'Unspecified'}</p><h3>Identity &amp; visible features</h3><div class="form-grid">{#each identityFields as field}<label>{c.name} · {labels[field]}<input bind:value={s[field]} oninput={manualDetails} maxlength="2000" placeholder={field==='age'?'Actual chronological age':field==='apparentAge'?'Visible age, e.g. 30 or early thirties':field==='gender'?'Identity, e.g. man':field==='presentation'?'Visible presentation, e.g. masculine or androgynous':''} /></label>{/each}</div>
        <p class="muted">Pictures use apparent age when filled, otherwise actual age; presentation takes priority over gender identity. A centuries-old character can appear thirty without sending centuries-old age to the image model.</p>
        {#if !(s.apparentAge.trim()||s.age.trim()) || !(s.presentation.trim()||s.gender.trim())}<p class="muted">{c.name}: {!(s.apparentAge.trim()||s.age.trim())?'visible age is unspecified':''}{!(s.apparentAge.trim()||s.age.trim())&&!(s.presentation.trim()||s.gender.trim())?' and ':''}{!(s.presentation.trim()||s.gender.trim())?'gender / presentation is unspecified':''}. Fill these above when relevant; No NSFW does not supply either detail.</p>{/if}
        <button onclick={()=>rememberIdentity(c.id)} disabled={JSON.stringify(visualIdentitySchema.parse(c.visual || {}))===JSON.stringify(rememberedVisual(c.id))}>Remember visual identity · {c.name}</button><p class="muted">Saves reviewed visible features, apparent age and presentation for future pictures. Established actual age and gender stay unchanged; edit those in Records. Clothing and injuries are image-only overrides here.</p>
        <h3>Clothing &amp; action in this picture</h3><div class="form-grid">{#each shotFields as field}<label>{c.name} · {labels[field]}<input bind:value={s[field]} oninput={manualDetails} maxlength="2000" disabled={draft.framing==='portrait'&&['lower_body','footwear'].includes(field)} /></label>{/each}</div></details>{/if}{/each}
      <label class="check"><input type="checkbox" checked={draft.nonsexual||contentPolicy.storyRequiresNonsexual} onchange={e=>draft.nonsexual=e.currentTarget.checked} disabled={contentPolicy.storyRequiresNonsexual} aria-describedby="illustration-content-help" />Nonsexual, fully clothed image</label>
      <div id="illustration-content-help" class="muted" role="status">{#if contentPolicy.storyRequiresNonsexual}<p>Required by this story: Allow adult content is off in Settings → Story. Enable it there to make this image checkbox optional.</p>{:else if draft.nonsexual}<p>The nonsexual, fully clothed instruction is enabled for this image. Turn it off to remove the whole-image instruction.</p>{:else if !contentPolicy.individualNames.length}<p>No automatic nonsexual or fully clothed instruction is added. Existing outfit descriptions and story content notes still apply.</p>{/if}{#if contentPolicy.individualNames.length}<p>No NSFW remains enabled for: {contentPolicy.individualNames.join(', ')}. The image checkbox does not override these profiles; change an intended character’s No NSFW setting in Records → Cast.</p>{/if}<p>Portrait variables omit lower-body clothing and footwear.</p></div>
      <label>Prompt format<select aria-label="Prompt format" bind:value={draft.promptMode}><option value="natural">Natural language · Krea / Z-Image</option><option value="template">Custom prompt template</option></select></label><p class="muted">Natural language includes the selected visual details, age and presentation when supplied, separate cast descriptions, framing, setting, light and art direction. Detail switches and shot placement also apply to custom templates. A complete prompt override uses only its own text.</p>
      {#if draft.promptMode==='template'}<details open><summary>Prompt template &amp; variables</summary><label>Image template<textarea bind:value={draft.template} maxlength="10000"></textarea></label><div class="row"><label>Insert variable<select bind:value={variable}>{#each illustrationVariables as v}<option value={v}>{v}</option>{/each}</select></label><button onclick={()=>draft.template+=' {{'+variable+'}}'}>Insert variable</button></div><p class="muted">{'{{subjects}}'} keeps group members in separate named blocks. The {'{{subject.…}}'} variables refer to the first depicted cast member. {'{{subject.age}}'} means visible age and {'{{subject.gender}}'} means visible presentation. Use {'{{subject.actual_age}}'} or {'{{subject.gender_identity}}'} only when you explicitly want identity metadata. Missing single-character visual identity is appended.</p></details>{/if}
      <label>Negative prompt<textarea bind:value={draft.negative} maxlength="10000"></textarea></label>{#if !images?.bindings.negative}<p class="muted">This workflow has no negative-prompt input mapped. Leave this empty, or map a negative input in the workflow settings. Describe the desired result in the positive prompt.</p>{/if}
      <label class="check"><input type="checkbox" bind:checked={override} onchange={e=>{override=e.currentTarget.checked;if(!override)draft.promptOverride='';}} />Use a one-image prompt override</label>{#if override}<label>One-image prompt override<textarea bind:value={draft.promptOverride} maxlength="15000" placeholder="Your complete prompt; individual content preferences are still appended."></textarea></label>{/if}
      <div class="heading-row prompt-heading"><h2>Resolved prompt</h2><div class="row"><button type="button" onclick={()=>copyPrompt(resolved.text)} disabled={Boolean(resolved.error)||!resolved.text}>Copy resolved prompt</button>{#if copyFeedback&&!copyFeedback.captured&&copyFeedback.text===resolved.text}<span class="muted" role="status">{copyFeedback.ok?'Copied':'Copy failed'}</span>{/if}<button onclick={()=>suggest()} disabled={!canSuggest||override}>Refresh prompt from story</button></div></div>
      <label class="check"><input type="checkbox" bind:checked={autoRefresh} disabled={!canSuggest||override} />Refresh stale story details before generating</label>
      <p class="muted prompt-freshness" role="status">{#if override}One-image override is active. Shot fields and templates do not replace it. Turn the override off to refresh from the story.{:else if !canSuggest}The preview updates from your current fields. Configure a text model for story-assisted refresh.{:else if needsRefresh}{preparation==='none'?'Story details have not been prepared yet.':'The source, cast, framing or selected moment changed.'} {autoRefresh?'Refresh now to review, or Generate will refresh them first.':'Automatic refresh is off; Generate uses the current fields.'}{:else if preparation==='manual'}Using your edited shot details. Generate preserves these fields; use Refresh prompt from story to update the scene, clothing and poses.{:else}Story details are current. Field and template edits update this preview automatically.{/if}</p>
      {#if resolved.error}<p class="error" role="alert">{resolved.error}</p>{/if}<pre class="dev-json illustration-prompt">{resolved.error ? '' : resolved.text}</pre>
      {#if images}<div class="form-grid"><label>Workflow<select bind:value={images.workflow} onchange={()=>workflowInfo=null}>{#if !workflows.some(w=>w.path===images!.workflow)}<option value={images.workflow}>{images.workflow}</option>{/if}{#each workflows as w}<option value={w.path}>{w.name}</option>{/each}</select></label><label>Variation of<select bind:value={draft.parentId}><option value={null}>Independent picture</option>{#each story.media.assets as a}<option value={a.id}>{a.caption || a.category}</option>{/each}</select></label></div>
        <details><summary>Workflow inputs &amp; generation settings</summary><p class="muted">These controls apply to this request. Unmapped controls are disabled; the workflow keeps its own value. Import workflows and save connection defaults in Settings → ComfyUI. This flow uses text-to-image inputs; a saved identity-reference picture is not sent to the workflow.</p><button onclick={inspectWorkflow}>Suggest workflow bindings</button>{#if workflowInfo}<pre class="dev-json">{JSON.stringify(workflowInfo.nodes,null,2)}</pre>{/if}<div class="form-grid">{#each ['prompt','negative','seed','width','height','steps','cfg','outputNode'] as key}<label>Binding · {key}<input bind:value={images.bindings[key as keyof typeof images.bindings]} maxlength="150" /></label>{/each}<label>Width<input type="number" bind:value={images.width} min="256" max="2048" step="8" disabled={!images.bindings.width} /></label><label>Height<input type="number" bind:value={images.height} min="256" max="2048" step="8" disabled={!images.bindings.height} /></label><label>Steps<input type="number" bind:value={images.steps} min="1" max="100" disabled={!images.bindings.steps} /></label><label>CFG<input type="number" bind:value={images.cfg} min="0" max="30" step="0.1" disabled={!images.bindings.cfg} /></label><label>Seed (-1 random)<input type="number" bind:value={images.seed} min="-1" max="2147483647" disabled={!images.bindings.seed} /></label></div></details>
      {/if}
      <button class="primary" onclick={generate} disabled={!images||Boolean(resolved.error)||Boolean(activeJob)}>{working?refreshing?'Refreshing prompt…':'Submitting…':'Generate illustration'}</button>
      {#if !images && !loading}<p class="muted">Open Settings → ComfyUI to load connection settings, then return to this composition.</p>{/if}
    </fieldset>
    {#if activeJob}<p class="notice" role="status">An illustration is already queued. You can edit the next shot while it finishes.</p><button type="button" onclick={()=>{selectJob(activeJob!);tab='results';}}>View queued illustration</button>{/if}
  {:else}
    <p class="muted">Queued work continues when you leave this page. Accept a result to keep it in the story; regenerating never removes previous pictures.</p>
    {#if jobs.length}<div class="form-grid generation-filters"><label>Find a generation<input type="search" bind:value={jobSearch} placeholder="Depicted subject or source passage" /></label><label>Generation status<select aria-label="Generation status" bind:value={jobStatus}><option value="all">All generations</option><option value="queued">Queued</option><option value="complete">Complete</option><option value="error">Failed</option></select></label></div><div class="row"><span class="muted" role="status">{visibleJobs.length} of {jobs.length} generations</span>{#if jobSearch||jobStatus!=='all'}<button type="button" onclick={()=>{jobSearch='';jobStatus='all';}}>Clear generation filters</button>{/if}</div>{/if}
    <div class="illustration-jobs">{#each visibleJobs as j}<button class:active={j.id===selectedJobId} aria-pressed={j.id===selectedJobId} disabled={working||busy} onclick={()=>selectJob(j)}><strong>{j.capture.snapshots.map(s=>s.name).join(', ') || 'Scene illustration'}</strong><small>{j.capture.source?.title || 'Reference art'} · {j.status} · seed {j.seed ?? 'workflow-defined'}</small></button>{:else}<p class="muted">{jobs.length ? 'No generations match these filters. Your selected generation stays open below.' : 'No illustration jobs yet. Compose a shot to get started.'}</p>{/each}</div>
    {#if job}<section class="editor illustration-result"><h2>{job.capture.source?.title || 'Reference illustration'}</h2><p class="muted">{job.status} · {(job.durationMs/1000).toFixed(1)} seconds · seed {job.seed ?? 'workflow-defined'}</p>{#if job.error}<p class="error" role="alert">{job.error}</p>{/if}
      {#if job.status==='queued'}<p>ComfyUI is working. You can return to the story while it finishes.</p>{/if}
      {#if job.images.length}<label>Generated output<select bind:value={outputIndex} disabled={working||busy}>{#each job.images as _,i}<option value={i}>Picture {i+1}</option>{/each}</select></label><img class="media-preview" src={job.images[outputIndex]} alt={caption || 'Generated story illustration'} /><a class="button" href={job.images[outputIndex]} target="_blank" rel="noreferrer">Open full-size preview ↗</a>{/if}
      <details><summary>Prompt and captured subjects</summary><div class="row"><button type="button" onclick={()=>copyPrompt(job!.capture.prompt,true)} disabled={!job.capture.prompt}>Copy captured prompt</button>{#if copyFeedback?.captured&&copyFeedback.text===job.capture.prompt}<span class="muted" role="status">{copyFeedback.ok?'Copied':'Copy failed'}</span>{/if}</div><pre class="dev-json">{job.capture.prompt}</pre>{#each job.capture.snapshots as s}<p><strong>{s.name}</strong><br />{s.appearance}<br />{s.outfit}</p>{/each}</details>
      {#if savedOutput}<p class="notice">Saved to the story{savedOutput.status==='superseded'?' as an earlier version':''}.</p><button class="primary" onclick={()=>onOpen(savedOutput!.id,'')}>Open saved picture ↗</button>
      {:else if job.status==='complete'}<label>Illustration caption<input bind:value={caption} maxlength="4000" disabled={working||busy} /></label><label>Save as<select bind:value={saveStatus} disabled={working||busy}><option value="canonical">Canonical illustration</option><option value="experimental">Visual experiment</option></select></label>{#if job.capture.draft.framing==='portrait'&&job.capture.draft.subjects.length===1}<label class="check"><input type="checkbox" bind:checked={setPortrait} disabled={working||busy} />Use as the character’s current portrait</label>{/if}<button class="primary" onclick={accept} disabled={working||busy}>{working?'Saving illustration…':'Keep illustration'}</button>{/if}
      <div class="row"><button onclick={reuse} disabled={working}>Reuse shot / new variation</button>{#if job.status!=='queued'}<button onclick={discard} disabled={working}>Discard preview</button>{/if}</div>
    </section>{/if}
  {/if}
</main>

<style>
  .illustration-fields{border:0;padding:0;margin:0;min-width:0}.illustration-fields>details,.illustration-subject{margin:22px 0;padding:16px;border:1px solid var(--line);border-radius:7px}.illustration-subject summary{cursor:pointer}.illustration-subject p{margin-top:14px}.illustration-prompt{max-height:360px}.prompt-heading{margin-top:24px;flex-wrap:wrap}.prompt-heading h2{margin:0}.prompt-freshness{margin-top:12px}.illustration-source{font:16px/1.8 Georgia,serif;max-height:360px;overflow:auto;margin-top:16px}.illustration-jobs{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:10px;margin:20px 0}.illustration-jobs button{text-align:left;overflow-wrap:anywhere}.illustration-jobs small{display:block;margin-top:6px;color:var(--muted)}.illustration-result>.row{margin-top:18px}.illustration-view>.tabs{flex-wrap:wrap}.illustration-result img{display:block;max-width:100%;max-height:650px;object-fit:contain}.illustration-view{overflow-wrap:anywhere}.illustration-view pre{white-space:pre-wrap}.illustration-result details{margin:20px 0}.illustration-fields:disabled{opacity:.75}@media(max-width:500px){.illustration-jobs{grid-template-columns:1fr}.illustration-fields .form-grid{grid-template-columns:1fr}}
</style>
